/* Elastyc.net layout adapter. Authentication is provided by the shared FrontAuth client. */
(function (global) {
  'use strict';

  var query = new URLSearchParams(global.location.search);
  var host = global.document.querySelector('.wf-login-layout [data-elastyc-front-auth-auto]');
  var isLoginPage = global.location.pathname === '/prijava' || (global.location.pathname === '/page.php'
    && query.get('channel') === 'candidate' && query.get('wf_path') === '/prijava');
  if (global.parent !== global || !isLoginPage || !host || host.hasAttribute('data-efa-preview')) return;

  var layout = host.closest('.wf-login-layout');
  var layoutHeading = layout.getAttribute('aria-labelledby');
  var english = query.get('portal_locale') === 'en'
    || global.document.documentElement.lang.toLowerCase().startsWith('en');
  if (english) {
    layout.lang = 'en';
    layout.querySelector('#wf-login-title').textContent = 'Sign in to Elastyc';
    layout.querySelector('.wf-login-layout__brand p').textContent = 'Business processes, communication, and AI.';
    var title = host.closest('.wf-front-auth')?.querySelector('.wf-front-auth__title');
    if (title) title.textContent = 'Your Elastyc account';
    global.document.title = 'Sign in | Elastyc';
  }

  host.removeAttribute('data-elastyc-front-auth-auto');
  var viewObserver = new MutationObserver(function () {
    var account = host.getAttribute('data-efa-view') === 'account';
    var heading = host.querySelector('.efa-account-name');
    layout.classList.toggle('wf-login-layout--account', account);
    layout.setAttribute('aria-labelledby', account && heading ? heading.id : layoutHeading);
  });
  viewObserver.observe(host, { attributes: true, attributeFilter: ['data-efa-view'] });

  function mount() {
    function currentClient() {
      var client = global.ElastycFrontAuth;
      return client && typeof client.version === 'number' && client.version >= 12;
    }
    function ready() {
      if (!currentClient()) {
        host.textContent = english ? 'Sign-in is currently unavailable.' : 'Prijava trenutno nije dostupna.';
        return;
      }
      global.ElastycFrontAuth.init({ host: host, title: !host.hasAttribute('data-efa-own-title') });
    }
    var styleUrl = '/common/Elastyc/FrontAuth/front-auth.css?v=5';
    if (!global.document.querySelector('link[href="' + styleUrl + '"]')) {
      var style = global.document.createElement('link');
      style.rel = 'stylesheet';
      style.href = styleUrl;
      global.document.head.appendChild(style);
    }
    if (currentClient()) {
      ready();
      return;
    }
    var script = global.document.createElement('script');
    script.src = '/common/Elastyc/FrontAuth/front-auth.js?v=12';
    script.onload = ready;
    script.onerror = function () {
      host.textContent = english ? 'Sign-in is currently unavailable.' : 'Prijava trenutno nije dostupna.';
    };
    global.document.head.appendChild(script);
  }
  if (global.document.readyState === 'loading') global.document.addEventListener('DOMContentLoaded', mount, { once: true });
  else mount();
})(window);

styles.content:
.wf-login-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  width: min(100% - 2rem, 64rem);
  margin: clamp(1.5rem, 5vw, 4.5rem) auto;
  border: 1px solid var(--wf-color-border, #d7dfe9);
  border-radius: var(--wf-radius, 12px);
  overflow: hidden;
  background: var(--wf-color-surface, #fff);
  color: var(--wf-color-text, #172033);
}
.wf-login-layout__brand, .wf-login-layout__form { min-width: 0; padding: clamp(1.5rem, 5vw, 3.75rem); }
.wf-login-layout__brand { display: flex; flex-direction: column; justify-content: center; background: var(--wf-color-secondary, #172033); color: #fff; }
.wf-login-layout__brand img { display: block; width: min(100%, 11.25rem); height: auto; margin-bottom: clamp(1.5rem, 4vw, 2.75rem); }
.wf-login-layout__brand h1 { color: inherit; font-size: clamp(1.65rem, 3vw, 2.5rem); line-height: 1.12; margin: 0; }
.wf-login-layout__brand p { color: inherit; opacity: .84; margin: .8rem 0 0; }
.wf-login-layout__form { display: flex; align-items: center; }
.wf-login-layout__form > * { flex: 1 1 auto; min-width: 0; }
@media (max-width: 720px) {
  .wf-login-layout { grid-template-columns: minmax(0, 1fr); }
  .wf-login-layout__brand img { width: 8.5rem; margin-bottom: 1rem; }
}
.wf-login-layout__form > * {
  max-width: 400px;
  margin-inline: auto;
}
.wf-login-layout .efa-provider.efa-brand {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 40px;
  padding: 0 40px;
  border: 1px solid #dadce0;
  border-radius: 4px;
  text-align: center;
}
.wf-login-layout .efa-provider.efa-brand > img {
  position: absolute;
  inset-inline-start: 12px;
  top: 50%;
  transform: translateY(-50%);
}
.wf-login-layout .efa-google-slot {
  width: 100%;
  min-width: 0;
  min-height: 40px;
  margin-block-end: 8px;
}
.wf-login-layout .efa-google-slot iframe {
  display: block;
  max-width: 100%;
}

.wf-login-layout.wf-login-layout--account {
  grid-template-columns: minmax(0, 1fr);
  width: min(100% - 2rem, 30rem);
}
.wf-login-layout--account .wf-login-layout__brand,
.wf-login-layout--account .wf-front-auth__title,
.wf-login-layout--account .efa-account-avatar[hidden] { display: none; }
.wf-login-layout--account .wf-login-layout__form { padding: clamp(1rem, 4vw, 1.875rem); }
.wf-login-layout--account [data-wf-load-native="auth"] { --wf-load-reserve: 0px; }
.wf-login-layout--account .efa-account-identity {
  display: flex;
  align-items: center;
  gap: .875rem;
}
.wf-login-layout--account .efa-account-avatar {
  display: grid;
  flex: none;
  place-items: center;
  width: 2.875rem;
  height: 2.875rem;
  border-radius: 50%;
  background: var(--wf-color-background, #f2f6f3);
  background: color-mix(in srgb, var(--wf-color-primary, #176b58) 12%, var(--wf-color-surface, #fff));
  color: var(--wf-color-primary, #176b58);
  font-weight: 700;
}
.wf-login-layout--account .efa-account-description {
  min-width: 0;
  overflow-wrap: anywhere;
}
.wf-login-layout--account .efa-account-name {
  margin: 0;
  color: var(--wf-color-text, #172033);
  font-size: clamp(1.125rem, 5vw, 1.5rem);
  line-height: 1.25;
  font-weight: 700;
}
.wf-login-layout--account .efa-account-company {
  margin: .25rem 0 0;
  color: var(--wf-color-muted, #516173);
}
.wf-login-layout--account .efa-root > :is(.efa-lead, .efa-error):not([hidden]) {
  margin: .75rem 0 0;
}
.wf-login-layout--account .efa-account-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .25rem .5rem;
  margin-block-start: 1.25rem;
}
.wf-login-layout--account .efa-account-actions > button {
  width: auto;
  min-height: 44px;
  margin: 0;
  padding-inline: .875rem;
}
.wf-login-layout--account .efa-account-actions .efa-link,
.wf-login-layout--account .efa-connection-status {
  color: var(--wf-color-muted, #516173);
}
.wf-login-layout--account .efa-connections {
  margin-block-start: .875rem;
  border-top: 1px solid var(--wf-color-border, #d7dfe9);
}
.wf-login-layout--account .efa-connections > summary {
  width: fit-content;
  min-height: 44px;
  padding: .75rem 0;
  line-height: 1.25rem;
  cursor: pointer;
  color: var(--wf-color-muted, #516173);
  font-weight: 600;
}
.wf-login-layout--account .efa-connections-list {
  display: grid;
  gap: .5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.wf-login-layout--account .efa-connections-list > li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: .5rem;
}
.wf-login-layout--account .efa-connections-list .efa-brand,
.wf-login-layout--account .efa-connections-list .efa-google-slot { margin: 0; }

.wf-login-layout--account .efa-connection-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: .25rem .5rem;
}
.wf-login-layout--account .efa-connection-actions .efa-unlink {
  width: auto;
  min-height: 44px;
  margin: 0;
  padding: 4px 8px;
  color: var(--wf-color-text, #172033);
}

.wf-login-layout .elastyc-front-auth .efa-error {
  padding: .75rem .875rem;
  border: 1px solid var(--wf-color-border, #d7dfe9);
  border-inline-start: 3px solid var(--wf-color-primary, #176b58);
  border-radius: 6px;
  background: var(--wf-color-background, #f4f6fa);
  color: var(--wf-color-text, #172033);
  font-size: .875rem;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.wf-login-layout .efa-error > strong {
  display: block;
  margin-block-end: .25rem;
  font-weight: 700;
}

.wf-login-layout .efa-error .efa-reauthenticate {
  width: auto;
  min-height: 44px;
  margin: .75rem 0 0;
}
